// Convert polygons to CGAL format
std::list<internal::Polygon_2> polygons1, polygons2;
std::vector<internal::Polygon_2> polygons;
std::vector<internal::Point_2> pwhs;

for (size_t i = 0; i < P1.size(); ++i) {
    internal::Polygon_2 polygon1, polygon2;
    // Convert P1 to polygon2
    for (const auto& p : P1) {
        internal::Point_2 pp1(p);
        polygon1.push_back(pp1);
    }
    for (const auto& p : P2) {
        internal::Point_2 pp2(p);
        polygon2.push_back(pp2);
    }

    internal::Point_2 result = internal::unite(P1, P2);

    // Convert result back to PolygonWithHoles2d format
    std::vector<PolygonWithHoles2d> res = internal::cgal::union2D(P1, P2);

    return res;
}

